  function Safe-Error($e){@{status='read-error-not-empty';exceptionType=$e.Exception.GetType().FullName;category=[string]$e.CategoryInfo.Category;diagnosticLine=$e.InvocationInfo.ScriptLineNumber;rawMessageSuppressed=$true}}
  function Scalar-Fields($o,[string[]]$names){
