   $fault.command=@{name=$cmd.Name;commandType=$cmd.CommandType.ToString();moduleName=$cmd.ModuleName;moduleVersion=$(if($cmd.Module){$cmd.Module.Version.ToString()}else{$null});modulePath=$(if($cmd.Module){$cmd.Module.Path}else{$null});moduleSha256=$(if($cmd.Module -and $cmd.Module.Path){(Get-FileHash -LiteralPath $cmd.Module.Path -ErrorAction Stop).Hash.ToLowerInvariant()}else{$null});parameterSets=$sets}
