   $physical=@($sets|Where-Object {@($_.parameters|Where-Object {$_.name -ceq 'PhysicalDisk' -and $_.type -cin @('Microsoft.Management.Infrastructure.CimInstance','Microsoft.Management.Infrastructure.CimInstance[]')}).Count -eq 1 -and @($_.parameters|Where-Object {$_.mandatory -and $_.name -cnotin $common -and $_.name -cne 'PhysicalDisk'}).Count -eq 0})
   if($noArg.Count){$fault.invocation='qualified-zero-required-argument-GET';$domains=@(& $cmd -ErrorAction Stop)}
   elseif($physical.Count -and $objects.Count -eq 8){$fault.invocation='qualified-PhysicalDisk-input-set; not a positional disk/domain mapping';$domains=@(& $cmd -PhysicalDisk $objects -ErrorAction Stop)}
   else{throw 'No supported installed bounded GET parameter set'}
